(()=>{const panel=document.querySelector('.product-balm');if(!panel)return;const surfaces=[panel.querySelector('.product-visual'),panel.querySelector('.scene-backdrop')];const canvases=surfaces.map(s=>{const c=document.createElement('canvas');c.className='ocean-motion';c.setAttribute('aria-hidden','true');s.append(c);return c;});const button=document.createElement('button');button.type='button';button.className='water-control';panel.querySelector('.product-copy').append(button);SFEnvironment({kind:'water',source:panel.querySelector('.product-visual img'),surfaces,canvases,button,panel,observe:document.querySelector('.scene-pin'),label:'ocean'});})();
